import { Pressable, View } from 'react-native';
import { useTranslation } from '../../i18n';
import { Badge, type BadgeAction } from '../ui/Badge';
import { Icon } from '../ui/Icon';
import { Typography } from '../ui/Typography';

/**
 * A Session in a list (Aksi redesign › SessionCard): one card, every
 * lifecycle state, from the fields the session list already returns.
 *
 * - Eyebrow: the caller's date · time, uppercase, with a repeat icon for a
 *   Session generated by a Recurring Schedule. Status pill on the right.
 * - Title in Saira, then "Sport · Activity type · location".
 * - Footer: price on the left, capacity on the right. With a player limit
 *   it is "6/12" over a 6px ink bar (never heat: heat is for Live); without
 *   one, "5 players" and no bar.
 *
 * The state comes from `statusAction` (sessionStatusColor's mapping of
 * lifecycleStatus), so callers pass nothing new to get it:
 * - live (in_progress): 2px heat border; the footer is the player count and
 *   "Open matches". The caller's `dateTime` reads "Today · 07:00–09:00".
 * - draft: 2px dashed border-strong, no background, no footer.
 * - completed / cancelled: sunken background, no footer; cancelled strikes
 *   the title through.
 *
 * Every string is passed in already formatted, except the generic player
 * count and "Open matches". Renders only (DOMAIN_UI.md): `onPress` is a
 * plain callback.
 */

type SessionCardProps = {
  title: string;
  subtitle?: string; // location
  dateTime?: string; // formatted date · time
  status?: string;
  statusAction?: BadgeAction;
  joinedCount?: number;
  maxParticipants?: number;
  /** Translated sport, e.g. "Tennis". */
  sport?: string;
  /** Translated activity type, e.g. "Doubles". */
  activityType?: string;
  /** "Free", "Rp 50.000 per person", "Split bill". */
  priceLabel?: string;
  isRecurring?: boolean;
  onPress?: () => void;
  className?: string;
};

export function SessionCard({
  title,
  subtitle,
  dateTime,
  status,
  statusAction = 'muted',
  joinedCount,
  maxParticipants,
  sport,
  activityType,
  priceLabel,
  isRecurring = false,
  onPress,
  className = '',
}: SessionCardProps) {
  const { t } = useTranslation();
  const isLive = statusAction === 'live';
  const isDraft = statusAction === 'draft';
  const isCancelled = statusAction === 'cancelled';
  const isPast = statusAction === 'completed' || isCancelled;
  const showFooter = !isDraft && !isPast;

  const frame = isLive
    ? 'bg-surface dark:bg-surface-dark border-2 border-heat'
    : isDraft
      ? 'border-2 border-dashed border-border-strong dark:border-border-strong-dark'
      : isPast
        ? 'bg-surface-sunken dark:bg-surface-sunken-dark border border-surface-sunken dark:border-surface-sunken-dark'
        : 'bg-surface dark:bg-surface-dark border border-border dark:border-border-dark';

  const line = [sport, activityType, subtitle].filter(Boolean).join(' · ');
  const hasLimit = maxParticipants != null && maxParticipants > 0;
  const fill = hasLimit && joinedCount != null ? Math.min(1, joinedCount / maxParticipants) : 0;

  return (
    <Pressable
      onPress={onPress}
      disabled={!onPress}
      accessibilityRole={onPress ? 'button' : undefined}
      className={`rounded-xl px-4 py-3.5 gap-2 ${onPress ? 'active:opacity-70' : ''} ${frame} ${className}`}
    >
      <View className="flex-row items-center justify-between gap-2">
        <View className="flex-row items-center gap-1.5 flex-1">
          {dateTime ? (
            <Typography variant="overline" color="muted" numberOfLines={1} className="flex-shrink">
              {dateTime}
            </Typography>
          ) : null}
          {isRecurring ? (
            <View accessible accessibilityLabel={t('cardRepeatsWeekly')}>
              <Icon name="repeat" size="xs" color="muted" />
            </View>
          ) : null}
        </View>
        {status ? <Badge action={statusAction} text={status} caps /> : null}
      </View>

      <Typography
        variant="title"
        numberOfLines={2}
        className={isCancelled ? 'line-through text-ink-muted dark:text-ink-muted-dark' : ''}
      >
        {title}
      </Typography>

      {line ? (
        <Typography variant="body" color="muted" className="text-[13px] leading-[18px]" numberOfLines={1}>
          {line}
        </Typography>
      ) : null}

      {showFooter && isLive ? (
        <View className="flex-row items-center justify-between pt-2.5 border-t border-border dark:border-border-dark">
          <Typography variant="label">{joinedCount != null ? t('cardPlayers', joinedCount) : ''}</Typography>
          <Typography variant="label" color="brand">
            {t('cardOpenMatches')}
          </Typography>
        </View>
      ) : null}

      {showFooter && !isLive && (priceLabel || joinedCount != null) ? (
        <View className="gap-1.5 pt-1.5">
          <View className="flex-row items-center justify-between gap-2">
            <Typography variant="body" color="muted" className="text-[13px] leading-[18px] font-semibold flex-shrink" numberOfLines={1}>
              {priceLabel ?? ''}
            </Typography>
            {joinedCount != null ? (
              <Typography
                variant="body"
                className="text-[13px] leading-[18px] font-semibold"
                style={{ fontVariant: ['tabular-nums'] }}
              >
                {hasLimit ? `${joinedCount}/${maxParticipants}` : t('cardPlayers', joinedCount)}
              </Typography>
            ) : null}
          </View>
          {hasLimit && joinedCount != null ? (
            <View className="h-1.5 rounded-full overflow-hidden bg-surface-sunken dark:bg-surface-sunken-dark">
              <View className="h-full rounded-full bg-ink dark:bg-ink-dark" style={{ width: `${fill * 100}%` }} />
            </View>
          ) : null}
        </View>
      ) : null}
    </Pressable>
  );
}
